package com.bank.redrive.model;

import java.math.BigDecimal;

public class DeadLetterEntry {
    private final String tradeId;      // business id for idempotency
    private final String accountId;
    private final BigDecimal amount;
    private final String errorReason;  // captured when it failed
    private final boolean malformed;   // true if structurally unprocessable

    public DeadLetterEntry(String tradeId, String accountId, BigDecimal amount,
                           String errorReason, boolean malformed) {
            this.tradeId = tradeId;
            this.accountId = accountId
            this.amount = amount;
            this.errorReason = errorReason;
            this.malformed = malformed;
    }
    public String getTradeId() { return tradeId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public String getErrorReason() { return errorReason; }
    public boolean isMalformed() { return malformed; }

    @Override public String toString() {
        return "DLT[" + tradeId + " " + accountId + " " + amount
             + " reason='" + errorReason + "' malformed=" + malformed + "]";
    }
}
