package com.bank.redrive.tool;

import com.bank.redrive.consumer.IdempotentSettlementConsumer;
import com.bank.redrive.model.DeadLetterEntry;
import com.bank.redrive.model.RedriveDecision;
import java.util.*;
import java.util.logging.*;

// Operator tool: inspect each DLT entry, decide replay vs discard,
// republish replayable ones (throttled) to the reprocessing consumer.
public class RedriveTool {
    private static final Logger log = Logger.getLogger(RedriveTool.class.getName());

    private final IdempotentSettlementConsumer consumer;
    private int replayed = 0, discarded = 0;

    public RedriveTool(IdempotentSettlementConsumer consumer) { this.consumer = consumer; }

    // Inspect: classify an entry. Malformed -> discard; otherwise replay.
    public RedriveDecision inspect(DeadLetterEntry e) {
        if (e.isMalformed()) {
            log.warning("Inspect " + e.getTradeId() + " -> DISCARD (malformed, would re-poison)");
            return RedriveDecision.DISCARD;
        }
        log.info(() -> "Inspect " + e.getTradeId() + " -> REPLAY (fix deployed, now processable)");
        return RedriveDecision.REPLAY;
    }

    public void redrive(List<DeadLetterEntry> entries) {
        for (DeadLetterEntry e : entries) {
            RedriveDecision decision = inspect(e);
            if (decision == RedriveDecision.DISCARD) {
                discarded++;
                continue; // audit trail would be written here
            }
            // throttle point: in production, rate-limit here
            consumer.onReplayed(e);   // idempotent consumer handles duplicates
            replayed++;
        }
        log.info("Redrive complete: replayed=" + replayed + ", discarded=" + discarded);
    }
}
