package com.bank.redrive.consumer;

import com.bank.redrive.model.DeadLetterEntry;
import java.util.*;
import java.util.logging.*;

// Idempotent: applies each tradeId at most once, so replays cause no duplicate side effects.
public class IdempotentSettlementConsumer {
    private static final Logger log = Logger.getLogger(IdempotentSettlementConsumer.class.getName());

    private final Set<String> appliedTradeIds = new HashSet<>(); // in prod: a DB unique key
    private int applied = 0, skipped = 0;

    // Pretend a previously applied trade already exists (partial processing before failure).
    public void markAlreadyApplied(String tradeId) { appliedTradeIds.add(tradeId); }

    public void onReplayed(DeadLetterEntry e) {
        if (appliedTradeIds.contains(e.getTradeId())) {
            log.warning("Skip " + e.getTradeId() + " (already applied) — idempotent, no double settle");
            skipped++;
            return;
        }
        appliedTradeIds.add(e.getTradeId());
        applied++;
        log.info(() -> "Settled on replay: " + e.getTradeId() + " " + e.getAmount());
    }

    public int getApplied() { return applied; }
    public int getSkipped() { return skipped; }
}
