package com.bank.redrive;

import com.bank.redrive.consumer.IdempotentSettlementConsumer;
import com.bank.redrive.model.DeadLetterEntry;
import com.bank.redrive.tool.RedriveTool;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class RedriveDemo {
    private static final Logger log = Logger.getLogger(RedriveDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IdempotentSettlementConsumer consumer = new IdempotentSettlementConsumer();
        // TRD-002 was partially applied before it failed earlier.
        consumer.markAlreadyApplied("TRD-002");

        RedriveTool tool = new RedriveTool(consumer);

        List<DeadLetterEntry> dlt = List.of(
            new DeadLetterEntry("TRD-001", "SAV2001", new BigDecimal("500000"),
                "false threshold rejection (bug now fixed)", false),
            new DeadLetterEntry("TRD-002", "CUR3001", new BigDecimal("20000"),
                "transient DB timeout (already applied once)", false),
            new DeadLetterEntry("TRD-BAD", "????",     new BigDecimal("0"),
                "malformed account id", true));

        tool.redrive(dlt);
        log.info("Consumer result: applied=" + consumer.getApplied()
            + ", skipped(duplicate)=" + consumer.getSkipped());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
